RAW=sql("SELECT json_build_object('readAt',clock_timestamp(),'archiveMode',current_setting('archive_mode'),'archiveTimeout',current_setting('archive_timeout'),'archiver',(SELECT row_to_json(x) FROM (SELECT archived_count,last_archived_wal,last_archived_time,failed_count,last_failed_time,(last_failed_time IS NOT NULL AND (last_archived_time IS NULL OR last_failed_time>last_archived_time)) AS unhealthy FROM pg_stat_archiver) x),'titleNormalizedNull',(SELECT count(*) FROM novel WHERE title_normalized IS NULL));")
data=next(json.loads(l) for l in RAW.splitlines() if l.startswith('{'));assert data['archiveMode']=='on' and not data['archiver']['unhealthy'] and data['archiver']['archived_count']>0, 'WAL archiver unhealthy'
info=json.loads(run(['docker','inspect',NAMES['backup-timer']]).stdout)[0];env=dict(v.split('=',1) for v in info['Config']['Env']);assert env['PREPROD_BASE_BACKUP_MIN_AGE_SECONDS']=='604800' and env['PREPROD_BACKUP_INTERVAL_SECONDS']=='86400', 'production backup cadence differs from SOP'
cmd="find /var/lib/cps-novel/backups/base -mindepth 2 -maxdepth 2 -type f -name VERIFIED -print | while IFS= read -r p; do printf 'BASE_FILE=%s\n' \"$p\"; cat \"$p\"; printf '\n'; sha256sum \"$(dirname \"$p\")/backup_manifest\"; done"
r=run(['docker','exec',NAMES['backup-timer'],'bash','-c',cmd]);rows=r.stdout.split('BASE_FILE=')[1:];bases=[]
for block in rows:
 lines=block.splitlines();kv=dict(l.split('=',1) for l in lines if '=' in l and not l.startswith('BASE_FILE='));epoch=int(kv['verified_epoch']);manifest_line=next(l for l in lines if len(l.split())==2 and len(l.split()[0])==64);assert manifest_line.split()[0]==kv['manifest_sha256'], 'base manifest checksum mismatch';bases.append({'marker':lines[0],'verifiedAt':kv['verified_at'],'verifiedEpoch':epoch,'manifestSha256':kv['manifest_sha256'],'startWal':kv['start_wal']})
assert bases, 'no verified base backup'
latest=max(bases,key=lambda b:b['verifiedEpoch']);age=datetime.datetime.now(datetime.timezone.utc).timestamp()-latest['verifiedEpoch'];assert 0<=age<=691200, 'latest base backup stale'
logical=json.loads(pathlib.Path('/opt/cps-novel/shared/backups/last-success.json').read_text());logicalAge=(datetime.datetime.now(datetime.timezone.utc)-datetime.datetime.fromisoformat(logical['finishedAt'].replace('Z','+00:00'))).total_seconds();assert logical['exitCode']==0 and 0<=logicalAge<=93600, 'daily logical backup stale'
ready=int(run(['docker','exec',NAMES['postgres'],'bash','-c',"find \"$PGDATA/pg_wal/archive_status\" -maxdepth 1 -type f -name '*.ready' | wc -l"]).stdout.strip())
print('BACKUP_FRESHNESS='+json.dumps({'at':stamp(),'database':data,'baseCadenceSeconds':604800,'baseMaxAgeSeconds':691200,'logicalCadenceSeconds':86400,'logicalMaxAgeSeconds':93600,'latestBase':latest,'latestBaseAgeSeconds':age,'logicalLastSuccess':logical,'logicalAgeSeconds':logicalAge,'walReadyCount':ready}));print('A3_BACKUP_FRESHNESS=PASS')
